-- Split RSC (q4_comp_2026) drafts #33, #34, #35 into three trainings, one per store type (2026-10-06).
-- Run as an admin on nudgeai. Nothing published changes: q4_comp_2026 keeps its live version #21, its
-- assignments and everyone's progress. The new trainings are drafts: not in the app until published AND assigned.
-- Each moved draft gets a new revision, so it needs a fresh preview call before it can be published.
--
-- Safe to check first: step 1 shows the three drafts as they are. If any shows a different status or revision
-- than in_review / 2, someone edited it since this script was made: stop, and ask for a new script.

USE nudgeai;

-- Step 1: look (expect three rows: in_review, revision 2)
SELECT version_id, training_id, status, revision, updated_at FROM training_versions WHERE version_id IN (33, 34, 35);
SELECT training_id FROM trainings WHERE training_id LIKE 'rsc_q4_comp_2026_%';  -- expect none

-- Step 2: create the trainings and move the drafts (one transaction)
START TRANSACTION;
-- #33 -> rsc_q4_comp_2026_fiber
INSERT INTO trainings (training_id, title, description, status, completion_type, uses_location, completion_key,
                       profile_id, app_title, category, tags, is_required, app_status, created_at, updated_at)
SELECT 'rsc_q4_comp_2026_fiber', 'RSC Sales Incentive Plan – Fiber', description, 'draft', completion_type, 0, completion_key,
       profile_id, 'RSC Sales Incentive Plan – Fiber', category, tags, is_required, app_status, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM trainings WHERE training_id = 'q4_comp_2026';

UPDATE training_versions
SET training_id = 'rsc_q4_comp_2026_fiber', status = 'draft', notes = 'Moved from q4_comp_2026 (draft #33) on 2026-10-06 and made Fiber only: other store types'' lines removed, no store-type tags. Check it, make a preview call, then submit.',
    content = '{"quiz": {"sections": {"A": {"name": "eligibility and the Perfect 10 bonus", "topics": [5, 10]}, "B": {"name": "accessories and plan changes", "topics": [1, 9]}, "C": {"name": "Power Rank qualifiers", "topics": [4]}, "D": {"name": "chargebacks and cancellations", "topics": [12]}, "E": {"name": "your location''s Power Rank", "topics": [3, 4, 7]}}, "questions": [{"number": 1, "correct": "A", "options": {"A": "5.0", "B": "6.0", "C": "7.0"}, "section": "A", "question": "What is the minimum Power Rank required to qualify for sales incentives?", "explanation": "The minimum is a Power Rank of 5.0. Finish a month below 5.0 and you won''t qualify for a sales incentive payout that month, even if you made qualifying sales."}, {"number": 2, "correct": "C", "options": {"A": "Yes, all of them are commissionable", "B": "Only Apple-branded accessories are commissionable", "C": "No, none of those qualify"}, "section": "B", "question": "Are Apple-branded accessories, or accessories discounted to less than $14.99, commissionable?", "explanation": "None of those qualify. Apple-branded accessories are excluded regardless of price, and any accessory is excluded only if its final price is under $14.99, discounted or not. A discounted accessory still priced at $14.99 or more does count toward payout."}, {"number": 3, "correct": "B", "options": {"A": "$100", "B": "$250", "C": "$500"}, "section": "A", "question": "What additional bonus will you receive if you achieve a perfect Power Rank of 10.0?", "explanation": "Finishing the month at a perfect Power Rank of 10 earns you an additional $250 bonus, on top of whatever you''ve already earned through your qualifying sales."}, {"number": 4, "correct": "A", "options": {"A": "180 days", "B": "90 days", "C": "12 months"}, "section": "D", "question": "What is the chargeback period?", "explanation": "The chargeback period is 180 days. If a customer cancels or stops paying within that window, the original payout for that sale can be deducted from your sales incentive payout."}, {"number": 5, "correct": "A", "options": {"A": "True", "B": "False"}, "section": "B", "question": "True or false: the CSAT qualifier and additional Event SPIFF incentive are no longer part of the compensation plan.", "explanation": "True. The CSAT qualifier and the additional Event SPIFF incentive are no longer part of the compensation plan this quarter."}, {"number": 6, "correct": "B", "options": {"A": "False", "B": "True"}, "section": "D", "question": "True or false: if you activate a PPVGA and the customer cancels the line during the same month it was sold, it will negatively affect your Power Rank.", "explanation": "True. A same-month cancellation can reduce both your Power Rank attainment and your sales incentive payout for that month."}, {"number": 7, "correct": "B", "options": {"A": "You need a 90% Next Up attach rate, or the category is zeroed out", "B": "You need a 70% Next Up attach rate on qualifying opportunities, including upgrades and new lines; missing it caps your Total Opportunities points at 50%", "C": "There''s no qualifier; Total Opportunities points are unconditional"}, "section": "C", "question": "How does the Next Up qualifier affect the Total Opportunities metric?", "explanation": "You need at least a 70% Next Up attach rate on qualifying opportunities, including upgrades and new lines. If you miss that qualifier, your Total Opportunities points are capped at 50% of what''s available."}, {"number": 8, "correct": "A", "options": {"A": "You need at least an 8% HTP attach rate in addition to your Protection Attach Rate goal; missing it caps your Protection points at 50%", "B": "You need at least a 15% HTP attach rate, or Protection points are zeroed out", "C": "HTP has no effect on the Protection metric"}, "section": "C", "question": "How does the HTP qualifier affect the Protection metric?", "explanation": "You need an HTP attach rate of at least 8%, in addition to meeting your Protection Attach Rate goal. Miss the HTP qualifier, and your Protection points are capped at 50% of what''s available."}, {"number": 9, "section": "E", "correct": "A", "options": {"A": "PPVGA 30%, New Fiber Gross Adds 20%, Accessories 15%, Protection with the HTP qualifier 15%", "B": "PPVGA 30%, AIA 20%, Total Opportunities 15%, Plus 1s 15%", "C": "New Fiber Gross Adds 30%, PPVGA 20%, Protection 15%, Accessories 15%"}, "question": "Which of these lists the four most heavily weighted metrics for a Fiber location?", "explanation": "The four most heavily weighted metrics for a Fiber location are PPVGA at 30%, New Fiber Gross Adds at 20%, Accessories at 15%, and Protection, with the HTP qualifier, at 15%."}, {"number": 10, "correct": "B", "options": {"A": "One more opp. It would give you an extra 10 points, while the additional HTP would only increase your score by 7.5 points", "B": "One more HTP sale. It would unlock full Protection points, increasing your score by 7.5 points, while the additional opp would only increase your points by 1", "C": "Trick question. Selling either would have the exact same impact on your Power Rank"}, "section": "E", "question": "It''s close to the end of the month. You''re one opp away from hitting 90% of your opps goal, and you''re crushing your Protection goal, but losing half your Protection points because you''re short one HTP sale. Which sale would have a bigger impact on your Power Rank: one more opp, or one more HTP sale?", "explanation": "The HTP sale. It would unlock full Protection points, adding 7.5 points to your score, while the additional opp would only add 1 point."}]}, "format": 1, "training": {"lines": {"closing": "Great work — you''ve completed this quarter''s compensation training! Keep your Sales Incentive Plan and Power Rank Definitions handy on My Pay, and partner with your RSM anytime you want to build a plan to move up a Power Rank tier. Thanks for taking the time today!", "quiz_intro": "That covers the full compensation plan. Now let''s put it to the test — I''ll ask you 10 questions covering everything we just went through. You''ll need all 10 correct to complete this training, and if you miss any, we''ll go back over just those areas together.", "first_message": "Hey! I''m {trainer_name}, your trainer for the RSC Sales Incentive Plan and Power Ranks for October 2026. We''ll walk through what''s new — eligibility, bonuses, and how your Power Rank is calculated — and it should take about 10 to 15 minutes. Here''s how it''ll go: first we''ll cover everything together, then you''ll take a mandatory 10-question quiz — you''ll need to get all 10 right to complete the training. Ready to get started?", "perfect_score": "That''s a perfect score! You''ve shown you know this quarter''s compensation plan inside and out.", "already_passed": "Welcome back! You''ve already completed this quarter''s compensation training — nice work. Would you like a quick refresher on anything, like how Power Rank is calculated for your location, or are you all set?", "location_unknown": "I couldn''t confirm your store''s location type, so I''ll use the Fiber version as a general reference. Check with your store manager which location type applies to you.", "feedback_question": "Before we wrap up — on a scale of 1 to 10, how would you rate this training? And in a sentence or two, what worked for you and what didn''t?", "welcome_back_quiz": "Welcome back! You''ve already finished the walkthrough, so today is the 10-question quiz. You''ll need all 10 correct, and if you miss any, we''ll go back over just those areas together.", "passed_after_retry": "That''s every section passed — nice work!", "welcome_back_retry": "Welcome back! You''ve already passed part of the quiz, so today we''ll just go back over the areas that still need a little work.", "welcome_back_walkthrough": "Welcome back! Let''s pick up where we left off."}, "title": "RSC Sales Incentive Plan – Fiber", "company": "Prime Communications", "opening": [{"ask": "Do you have your October 2026 Sales Incentive Plan and Power Rank schedule pulled up or printed and ready to go right now?", "otherwise": "If they''re not ready, say: \\"No problem — you''ll find both the Sales Incentive Plan and your Power Rank schedule under My Pay, on the Human Resources page. Go ahead and pull those up or print them, then just start a new session with me whenever you''re ready to continue.\\" Then call end_call."}, {"ask": "Has your store manager or district manager had a chance to review your Sales Incentive Plan and Power Rank with you yet?", "otherwise": "If not, say: \\"For best results and understanding, have your supervisor review these important topics with you in person before completing this course. Would you like to continue now, or come back later to complete our session?\\" If they want to come back later, say: \\"No problem — let your supervisor know, and we''ll pick this up whenever you''re ready.\\" Then call end_call."}, {"say": "Great — let''s dive in!"}], "trainer_name": "Anne", "uses_location": false}, "vocabulary": null, "knowledge_base": {"topics": [{"lines": [{"kind": "ask", "text": "Can you tell me the three primary ways you can earn money at Prime Communications?", "prefix": "Ask: "}, {"kind": "expected", "text": "hourly pay; sales incentives; and contests, spiffs and vendor incentives.", "prefix": "Expected answer: "}, {"kind": "if_right", "text": "Exactly, hourly pay, sales incentives, and contests, spiffs and vendor incentives. If not, give the full list briefly.", "prefix": "If they get it: "}, {"kind": "then_say", "text": "One flag for this quarter, the CSAT qualifier and Event SPIFF incentive are no longer part of the plan.", "prefix": "Then say: "}, {"kind": "text", "text": "", "prefix": ""}], "title": " Ways to earn", "number": 1}, {"lines": [{"kind": "ask", "text": "What must you do to ensure you''re paid accurately for all the hours you work?", "prefix": "Ask: "}, {"kind": "expected", "text": "clock in and out correctly.", "prefix": "Expected answer: "}, {"kind": "then_add", "text": "If you miss a punch, submit a Time Punch Correction under My Page in the Prime Portal, as soon as you notice it.", "prefix": "Then add: "}, {"kind": "text", "text": "", "prefix": ""}], "title": " Hourly pay and timekeeping", "number": 2}, {"lines": [{"kind": "say", "text": "Your Power Rank structure varies based on your primary location. Because you work in a Fiber location, your Power Rank consists of 30 percent PPVGA, 20 percent New Fiber, 15 percent Accessories, 15 percent Protection with the HTP qualifier, 10 percent Total Opportunities with the Next Up qualifier, and 10 percent AIA. PPVGA and New Fiber account for half your total Power Rank, so strong performance in those two areas makes the biggest difference.", "prefix": "Say: "}, {"kind": "ask", "text": "Looking at your Power Rank structure, which metric has the greatest impact on your overall score?", "prefix": "Ask: "}, {"kind": "expected", "text": "PPVGA", "prefix": "Expected answer: "}, {"kind": "accept", "text": "postpaid voice, postpaid voice gross adds, voice lines, new lines, or any other name for the same metric.", "prefix": "Accept: "}, {"kind": "if_missed", "text": "Not quite. The biggest piece of your Power Rank is PPVGA, which is postpaid voice gross adds. It carries the most weight of any single metric, so it''s the one that moves your score the most.", "prefix": "If they miss it: "}, {"kind": "if_right", "text": "Exactly, PPVGA. It''s the biggest piece of your Power Rank, so every new postpaid voice line you add moves your score more than anything else.", "prefix": "If they get it: "}, {"kind": "text", "text": "", "prefix": ""}], "title": " Your Power Rank structure(Fiber)", "number": 3}, {"lines": [{"kind": "ask", "text": "What is the current Protection qualifier, and what happens if you miss it?", "prefix": "Ask: "}, {"kind": "expected", "text": "an 8 percent HTP attach rate; missing it caps your Protection points at 50 percent of what''s available. HTP stands for HomeTech Protection.", "prefix": "Expected answer: "}, {"kind": "then_say", "text": "Same idea applies to Total Opportunities, you need a 70 percent Next Up attach rate on eligible opportunities, or those points are capped at 50 percent too.", "prefix": "Then say: "}, {"kind": "text", "text": "", "prefix": ""}], "title": " Power Rank qualifiers", "number": 4}, {"lines": [{"kind": "ask", "text": "Does qualifying for a payout at Power Rank 5.0 automatically mean you''re meeting your role''s performance expectation?", "prefix": "Ask: "}, {"kind": "expected", "text": "No. An RSC''s on-level expectation is 6.0 or higher, and a Senior RSC''s is 7.0 or higher. 5.0 is only the minimum payout floor after ramp-up.", "prefix": "Expected answer: "}, {"kind": "then_say", "text": "Push beyond that where you can, Power Rank 9 or higher also unlocks the highest PPVGA and Internet payout tier.", "prefix": "Then say: "}, {"kind": "text", "text": "", "prefix": ""}], "title": " Eligibility versus performance expectations", "number": 5}, {"lines": [{"kind": "say", "text": "PPVGA stands for Postpaid Voice Gross Add, a new postpaid phone line. A wearable or tablet doesn''t count, that''s a Plus 1 instead. Your payout depends on two things: your final Power Rank tier, and the customer''s qualifying rate plan at activation, up to 80 dollars per qualifying PPVGA.", "prefix": "Say: "}, {"kind": "ask", "text": "You activate a new phone line on the Elite plan and finish the month with a Power Rank of 8. How much will you earn for that transaction?", "prefix": "Ask: "}, {"kind": "expected", "text": "40 dollars.", "prefix": "Expected answer: "}, {"kind": "text", "text": "After this topic, say a brief halfway line, such as: That''s halfway!", "prefix": ""}, {"kind": "text", "text": "", "prefix": ""}], "title": " PPVGA", "number": 6}, {"lines": [{"kind": "say", "text": "You can''t be eligible for both AT&T Fiber and AIA, the customer''s address determines which one applies. When you see an eligible Internet opportunity, sometimes called a green check, ask about their current provider and present your top offer.", "prefix": "Say: "}, {"kind": "ask", "text": "You help an existing copper customer upgrade to Fiber 1 GIG, and finish the month with a Power Rank of 9. How much will you earn for that transaction?", "prefix": "Ask: "}, {"kind": "expected", "text": "30 dollars, because this is a copper-to-fiber, or C2F, upgrade, not a brand-new Fiber sale, which is why the payout differs.", "prefix": "Expected answer: "}, {"kind": "text", "text": "", "prefix": ""}], "title": " Internet payouts", "number": 7}, {"lines": [{"kind": "ask", "text": "Earlier we established that a new watch or tablet doesn''t count as a PPVGA. What type of opportunity may it count as instead?", "prefix": "Ask: "}, {"kind": "expected", "text": "a Plus 1.", "prefix": "Expected answer: "}, {"kind": "then_say", "text": "Plus 1s are still a valuable sales opportunity, but they''re not one of the six Power Rank metrics for your location type.", "prefix": "Then say: "}, {"kind": "text", "text": "", "prefix": ""}], "title": " Plus 1 opportunities", "number": 8}, {"lines": [{"kind": "say", "text": "Accessory payout is based on qualifying units sold, not revenue. You need at least 10 qualifying units a month, priced 14.99 or more, split into two price tiers. Power Rank doesn''t affect this payout, total units does. Apple-branded accessories don''t qualify, but Beats does, even though Apple owns it.", "prefix": "Say: "}, {"kind": "ask", "text": "You sell a JBL speaker priced at 130 dollars and a pair of Apple AirPods priced at 200 dollars, finishing the month with 55 qualifying units. How much do you earn for each?", "prefix": "Ask: "}, {"kind": "expected", "text": "6 dollars for the JBL, because 55 units falls in the 50 to 69 unit tier, 100 dollars and up price category; and nothing for the AirPods, because Apple-branded accessories are excluded.", "prefix": "Expected answer: "}, {"kind": "text", "text": "", "prefix": ""}], "title": " Accessory payouts", "number": 9}, {"lines": [{"kind": "ask", "text": "What happens if you finish the month with a Power Rank of 10?", "prefix": "Ask: "}, {"kind": "expected", "text": "you earn an additional 250 dollar bonus, on top of your qualifying sales incentive payout.", "prefix": "Expected answer: "}, {"kind": "text", "text": "", "prefix": ""}], "title": " Perfect 10 bonus", "number": 10}, {"lines": [{"kind": "ask", "text": "When you check your Power Rank mid-month, is that number estimated or final?", "prefix": "Ask: "}, {"kind": "expected", "text": "estimated. It locks about 15 days after the month ends, once returns and cancellations settle.", "prefix": "Expected answer: "}, {"kind": "then_say", "text": "For example, if you complete 15 PPVGAs in the first 15 days of a 30-day month, the system would project roughly 30 for the full month. A day off can temporarily dip that projected trend, it adjusts once you''re back selling. Full detail on your goals and tiers is under the Power Rank Definitions link on My Pay.", "prefix": "Then say: "}, {"kind": "text", "text": "Then ask, as a reflection with no right or wrong answer: Take a moment to review your current Power Rank. Which metric is your greatest opportunity to improve? Acknowledge their choice, ask why, and encourage a specific plan with their RSM.", "prefix": ""}, {"kind": "text", "text": "", "prefix": ""}], "title": " Reading and monitoring Power Rank", "number": 11}, {"lines": [{"kind": "say", "text": "Sales are subject to a 180-day chargeback period. A same-month cancellation can hit both your Power Rank and payout; a later chargeback only affects the payout, not your current Power Rank. Track these under My Pay, then Commission Records.", "prefix": "Say: "}, {"kind": "ask", "text": "You activate a new line in October, but it charges back in December. How does that affect you?", "prefix": "Ask: "}, {"kind": "expected", "text": "the October payout is deducted from your sales incentive payout. It does not affect your current December Power Rank.", "prefix": "Expected answer: "}, {"kind": "text", "text": "", "prefix": ""}, {"kind": "text", "text": "REFERENCE: Metric nicknames", "prefix": ""}, {"kind": "text", "text": "Treat these as the same metric: Voice, PPVGA, VGA, voice lines, new wireless service and new lines. Fiber, BB, broadband, internet and fiber optic internet. Business Accounts, CRU, business lines and business. AIA, Internet Air and wireless internet. Protection, Insurance, P1 and P4.", "prefix": ""}, {"kind": "text", "text": "", "prefix": ""}, {"kind": "text", "text": "REFERENCE: Voice plan designations", "prefix": ""}, {"kind": "text", "text": "Not taught or quizzed. Use only if a trainee asks which payout tier their plan falls in, and just name the tier.", "prefix": ""}, {"kind": "text", "text": "AT&T voice plans fall into three account types: Business, Consumer and FirstNet. Business Unlimited plans are Ultimate 3.0, Premium 3.0, Advanced 3.0 and Standard 3.0. Consumer plans are Elite 2.0, Premium 2.0, Extra 2.0 and Value 2.0. FirstNet Unlimited pays as AT&T Premium 2.0. Business and Consumer plans pair up for payout: Business Unlimited Ultimate 3.0 pays as Elite 2.0, Premium 3.0 as Premium 2.0, Advanced 3.0 as Extra 2.0, and Standard 3.0 as Value 2.0.", "prefix": ""}, {"kind": "text", "text": "", "prefix": ""}, {"kind": "text", "text": "REFERENCE: Finding a store''s GL Code", "prefix": ""}, {"kind": "text", "text": "Not taught or quizzed. A store''s GL Code is the same as its store ID. Go to myprimeportal.com/store, click Detail View in the left sidebar under the store''s photo. The GL Code is the first line listed.", "prefix": ""}], "title": " Chargebacks", "number": 12}], "preamble": [], "ends_with_newline": true}}',
    revision = revision + 1, updated_at = UTC_TIMESTAMP(6)
WHERE version_id = 33 AND training_id = 'q4_comp_2026' AND status = 'in_review' AND revision = 2;
